{
  "pipeline_id": "chip-seq",
  "name": "ChIP-seq Analysis",
  "description": "Chromatin immunoprecipitation sequencing pipeline for mapping protein-DNA binding sites and histone modifications. Covers FastQC quality control, Trimmomatic adapter trimming, Bowtie2 alignment, SAMtools BAM filtering, and HOMER for peak calling and motif analysis. Suitable for transcription factor ChIP-seq (narrow peaks) and histone mark ChIP-seq (broad peaks).",
  "estimated_duration": "3-5 hours",
  "inputs": [
    {
      "name": "inputFastqChIP",
      "type": "file",
      "required": true,
      "description": "ChIP FASTQ file (treatment)"
    },
    {
      "name": "inputFastqInput",
      "type": "file",
      "required": true,
      "description": "Input/control FASTQ file"
    },
    {
      "name": "referenceGenome",
      "type": "string",
      "required": false,
      "default": "references/GRCh38/hg38.fa",
      "description": "Reference genome FASTA"
    },
    {
      "name": "sampleName",
      "type": "string",
      "required": false,
      "default": "chip_sample",
      "description": "Sample identifier"
    },
    {
      "name": "peakType",
      "type": "select",
      "required": false,
      "default": "narrow",
      "options": [
        "narrow",
        "broad"
      ],
      "description": "Peak type: narrow (TF) or broad (histone marks)"
    }
  ],
  "steps": [
    {
      "step": 1,
      "tool": "fastqc",
      "description": "QC on ChIP reads"
    },
    {
      "step": 2,
      "tool": "fastqc",
      "description": "QC on input/control reads (runs in parallel with step1_fastqc_chip)"
    },
    {
      "step": 3,
      "tool": "trimmomatic",
      "description": "Adapter trimming for ChIP reads",
      "after": [
        "step1_fastqc_chip"
      ]
    },
    {
      "step": 4,
      "tool": "trimmomatic",
      "description": "Adapter trimming for input/control reads",
      "after": [
        "step1_fastqc_input"
      ]
    },
    {
      "step": 5,
      "tool": "bowtie2",
      "description": "Align ChIP reads to reference genome",
      "after": [
        "step2_trim_chip"
      ]
    },
    {
      "step": 6,
      "tool": "bowtie2",
      "description": "Align input/control reads to reference genome",
      "after": [
        "step2_trim_input"
      ]
    },
    {
      "step": 7,
      "tool": "samtools",
      "description": "Filter, sort, and index ChIP BAM — remove unmapped and low-quality reads",
      "after": [
        "step3_align_chip"
      ]
    },
    {
      "step": 8,
      "tool": "samtools",
      "description": "Filter, sort, and index input BAM",
      "after": [
        "step3_align_input"
      ]
    },
    {
      "step": 9,
      "tool": "homer",
      "description": "Peak calling and motif enrichment analysis",
      "after": [
        "step4_filter_chip",
        "step4_filter_input"
      ]
    },
    {
      "step": 10,
      "tool": "homer",
      "description": "De novo and known motif enrichment in the called peaks",
      "after": [
        "step5_peaks"
      ]
    }
  ]
}

